mapper.select:
select ocr.*,pp.p_name pName from osm_commencement_report ocr
    left join Pre_Project pp on pp.p_id = ocr.p_id

    
        and pp.p_id = #{params.pId}
    
    
        
            
                and likePname(#{params.pName},pp.P_Id)=true
            
            
                and pp.p_name like concat('%',#{params.pName},'%')
            
        
    
    
        and ocr.using_seals = #{params.usingSeals}
    
    
        and ocr.seals_type = #{params.sealsType}
    
    
        and ocr.state = #{params.state}
    
    
        and ocr.handler_user_name like concat('%',#{params.handlerUserName},'%')
    
    
        and ocr.create_uname like concat('%',#{params.createUname},'%')
